#include <string>

void sort3(int* a, int* b, int* c) {}
bool parseTime(const std::string& text, int* hours, int* minutes) { return false; }
void minMax(const int* values, int count, int* minOut, int* maxOut) {}

solution.solution.cpp:
#include <cctype>
#include <string>

static void swapInts(int* x, int* y)
{
    const int old{ *x };
    *x = *y;
    *y = old;
}

void sort3(int* a, int* b, int* c)
{
    if (*a > *b) swapInts(a, b);
    if (*b > *c) swapInts(b, c);
    if (*a > *b) swapInts(a, b);
}

bool parseTime(const std::string& text, int* hours, int* minutes)
{
    const std::size_t colon{ text.find(':') };
    if (colon == std::string::npos || colon < 1 || colon > 2 || text.size() != colon + 3) return false;
    for (std::size_t i{ 0 }; i < text.size(); ++i)
        if (i != colon && !std::isdigit(static_cast<unsigned char>(text[i]))) return false;
    const int h{ std::stoi(text.substr(0, colon)) };
    const int m{ std::stoi(text.substr(colon + 1)) };
    if (h > 23 || m > 59) return false;
    if (hours) *hours = h;
    if (minutes) *minutes = m;
    return true;
}

void minMax(const int* values, int count, int* minOut, int* maxOut)
{
    if (count <= 0) return;
    int lo{ values[0] }, hi{ values[0] };
    for (int i{ 1 }; i < count; ++i)
    {
        if (values[i] < lo) lo = values[i];
        if (values[i] > hi) hi = values[i];
    }
    if (minOut) *minOut = lo;
    if (maxOut) *maxOut = hi;
}

unitTests:
TEST("sort3") {
    int a{ 3 }, b{ 1 }, c{ 2 };
    sort3(&a, &b, &c);
    CHECK_EQ(a, 1); CHECK_EQ(b, 2); CHECK_EQ(c, 3);
    int d{ 9 }, e{ 9 }, f{ -4 };
    sort3(&d, &e, &f);
    CHECK_EQ(d, -4); CHECK_EQ(e, 9); CHECK_EQ(f, 9);
    int g{ 5 }, h{ 4 }, i{ 3 };
    sort3(&g, &h, &i);
    CHECK_EQ(g, 3); CHECK_EQ(h, 4); CHECK_EQ(i, 5);
}
TEST("parseTime success") {
    int h{ -1 }, m{ -1 };
    CHECK(parseTime("12:45", &h, &m)); CHECK_EQ(h, 12); CHECK_EQ(m, 45);
    CHECK(parseTime("7:05", &h, &m)); CHECK_EQ(h, 7); CHECK_EQ(m, 5);
    CHECK(parseTime("00:00", &h, &m)); CHECK_EQ(h, 0); CHECK_EQ(m, 0);
}
TEST("parseTime failure writes nothing") {
    int h{ -1 }, m{ -1 };
    for (const char* bad : { "24:00", "12:60", "1245", "12:5", "ab:cd", "", ":30", "123:00", "12:345" })
    {
        CHECK(!parseTime(bad, &h, &m));
        CHECK_EQ(h, -1); CHECK_EQ(m, -1);
    }
}
TEST("parseTime with only one out-parameter") {
    int m{ -1 };
    CHECK(parseTime("9:30", nullptr, &m)); CHECK_EQ(m, 30);
    CHECK(parseTime("9:30", nullptr, nullptr));
}
TEST("minMax") {
    const int values[]{ 4, -2, 17, 0, 17, 3 };
    int lo{ 0 }, hi{ 0 };
    minMax(values, 6, &lo, &hi);
    CHECK_EQ(lo, -2); CHECK_EQ(hi, 17);
    int only{ 99 };
    minMax(values, 6, nullptr, &only); CHECK_EQ(only, 17);
    int untouched{ 1234 };
    minMax(values, 0, &untouched, nullptr); CHECK_EQ(untouched, 1234);
    minMax(values + 1, 1, &lo, &hi); CHECK_EQ(lo, -2); CHECK_EQ(hi, -2);
}

